/**
 * Authoring source for the "Moksy reviewer onboarding" track (slug moksy-reviewer-onboarding). For people joining Moksy as
 * reviewers (invited as customers) and for staff who answer or coordinate them (role-required for support and reviewer
 * coordinator): the route onto the Ladder, the five rungs, how a review works, what it pays, and the code of conduct.
 * Writes content/brand/moksy-reviewer-onboarding.json, loaded with
 *   npm run import:knowledge -- content/brand/moksy-reviewer-onboarding.json
 * Questions arrive as "review" and stay unpublished until an admin approves them at /admin/review/moksy-reviewer-onboarding.
 *   node scripts/build-moksy-reviewer-content.mjs
 *
 * Sources (moksy.ai repo, mokay.ai/), read 2026-10-11. The PUBLISHED reviewer pages are the reference:
 *   foundation/dictionary/public/i18n/en/pages/{reviewer-process,reviewer-levels,reviewer-payouts,reviewer-conduct,careers}.json
 *   docs/brand/MOKSY_LEXICON.md (vocabulary), docs/MOKSY_REVIEWER_ONBOARDING.md (an application builder, built on dev, 2026-09-13)
 *   docs/promo/LAUNCH_PROMO_SPEC.md (a PROPOSAL, 13 Aug 2026): used only for one dated caution about price tables
 * This track does NOT contain the Calibration's content (it is a blind test; nothing here prepares answers to it) and it
 * teaches no income promise: the payouts page gives worked examples, "not a promise of volume".
 * Published and internal documents disagree in places (number of rungs, disciplines versus Tracks versus 25 roles, who may
 * Sign-off): item 7 teaches those as "confirm before quoting". Figures are as published on 2026-10-11 and may change
 * (the page says operators can change the MOX conversion rate). Re-run the build when the pages change.
 * Each question lists the correct answer first; the build shuffles options with a seed taken from the prompt.
 */
import fs from "node:fs";
import path from "node:path";

const seed = (s) => { let h = 2166136261; for (const c of s) { h ^= c.charCodeAt(0); h = Math.imul(h, 16777619); } return h >>> 0; };
const rng = (s) => { let a = seed(s); return () => { a = (a + 0x6d2b79f5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; };
const q = (level, prompt, correct, wrong, hint, topic) => {
  if (wrong.length !== 3) throw new Error(`need 3 wrong options: ${prompt}`);
  const opts = [correct, ...wrong], r = rng(prompt);
  for (let i = opts.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [opts[i], opts[j]] = [opts[j], opts[i]]; }
  const keys = ["a", "b", "c", "d"];
  return { level, type: "mcq", prompt, options: opts.map((text, i) => ({ key: keys[i], text })), answer: keys[opts.indexOf(correct)], hint, topic };
};
const open = (level, prompt, answer, rubric, topic) => ({ level, type: "scenario", prompt, answer, rubric, topic });

